def semver_sort(versions):
    def parse(v):
        main = v
        build = None
        if '+' in main:
            main, build = main.split('+', 1)
        pre = None
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core = main
        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])
        if pre is not None:
            idents = pre.split('.')
            key_idents = []
            for ident in idents:
                if ident.isdigit():
                    key_idents.append((0, int(ident)))
                else:
                    key_idents.append((1, ident))
            has_pre = 0
            pre_key = tuple(key_idents)
        else:
            has_pre = 1
            pre_key = tuple()
        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

